    res.statusCode=200;res.setHeader('Content-Type','text/html; charset=utf-8');
    res.end(`<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Twitch und Discord verbinden · ACY Community</title><style nonce="${nonce}">:root{color-scheme:dark;font:16px/1.55 system-ui;background:#11131b;color:#eee}main{max-width:680px;margin:7vh auto;padding:24px;background:#1b1d29;border:1px solid #393449;border-radius:18px}p,li{color:#c1bfd0}a{color:#c3a4ff}button{font:inherit;background:#7652bd;color:white;border:0;border-radius:10px;padding:12px 16px;min-height:44px}button:disabled{opacity:.55}</style></head><body><main><h1>🔗 Twitch und Discord verbinden</h1><p>Mit deiner Zustimmung speichern wir die Twitch-ID und Discord-ID deiner Konten gemeinsam, damit ausgewählte Community-Fortschritte später plattformübergreifend angezeigt werden können.</p><ul><li>Deine vorhandenen XP oder Spielstände werden nicht kopiert oder zusammengeführt.</li><li>Für Twitch werden keine zusätzlichen Berechtigungen angefragt.</li><li>Du kannst die Verbindung jederzeit privat mit /trennen lösen; dein Fortschritt bleibt bestehen.</li><li>Der einmalige Startlink wird nach zehn Minuten ungültig.</li></ul><form method="post" action="/community/link/twitch"><input id="token" name="token" type="hidden"><button id="continue" type="submit" disabled>Weiter zu Twitch und verbinden</button></form><noscript><p role="alert">Für die sichere Weiterleitung zu Twitch muss JavaScript aktiviert sein. Öffne den Link danach erneut in Discord.</p></noscript><p id="status" role="status"></p><p><a href="/community">Abbrechen und zurück</a> · <a href="/community/datenschutz">Datenschutz</a></p></main><script nonce="${nonce}">(()=>{const token=location.hash.startsWith('#token=')?location.hash.slice(7):'';history.replaceState(null,'',location.pathname);if(/^[A-Za-z0-9_-]{43}$/.test(token)){document.querySelector('#token').value=token;document.querySelector('#continue').disabled=false}else document.querySelector('#status').textContent='Dieser Verknüpfungslink fehlt oder ist ungültig. Starte den Vorgang bitte erneut in Discord.'})()</script></body></html>`);
