  private async startAccountLink(req:IncomingMessage,res:ServerResponse):Promise<void>{
    if(this.rejectRateLimit(res,this.rates.consume('account-link-start',trustedClientAddress(req),10,10*60_000),'Zu viele Verknüpfungsversuche. Bitte später erneut versuchen.'))return;
    const origin=req.headers.origin;
    // Some embedded browsers send the opaque Origin value "null". This route
    // still requires the high-entropy, short-lived, single-use intent token
    // below, so treat that value like an omitted Origin rather than accepting
    // an arbitrary site. Any concrete foreign origin remains rejected.
    if(origin&&origin!=='null'){
      let normalizedOrigin:string;
      try{
        const parsed=new URL(origin);
        if(parsed.username||parsed.password||parsed.pathname!=='/'||parsed.search||parsed.hash)throw new Error('invalid origin');
        normalizedOrigin=parsed.origin;
      }catch{
        this.sendJson(res,403,{error:'Die Anfrage stammt nicht von dieser Website.'});return;
      }
      if(normalizedOrigin!==this.publicOrigin){this.sendJson(res,403,{error:'Die Anfrage stammt nicht von dieser Website.'});return;}
    }
    let raw='';for await(const chunk of req){raw+=chunk;if(raw.length>2_000){this.sendJson(res,400,{error:'Der Verknüpfungslink ist ungültig.'});return;}}
    const token=new URLSearchParams(raw).get('token')||'';
    if(!/^[A-Za-z0-9_-]{43}$/u.test(token)){this.sendJson(res,400,{error:'Der Verknüpfungslink ist ungültig. Starte den Vorgang bitte erneut in Discord.'});return;}
    const tokenHash=hash(token),now=Date.now(),intent=this.store.accountLinkIntent(tokenHash,now);
    if(!intent){this.sendJson(res,410,{error:'Der Verknüpfungslink ist abgelaufen oder wurde bereits verwendet. Starte den Vorgang bitte erneut in Discord.'});return;}
    const settings=this.store.config<{enabled?:boolean;accountLinkEnabled?:boolean}>('discord_integration',{});
    if(!settings.enabled||!settings.accountLinkEnabled){this.sendJson(res,403,{error:'Die Konto-Verknüpfung ist derzeit deaktiviert.'});return;}
    const state=randomBytes(24).toString('hex'),stateHash=hash(state),expiresAt=Math.min(now+OAUTH_STATE_MS,intent.expiresAt);
    let authorizationLocation:string,stateCookie:string;
    try{
      const auth=new URL('https://id.twitch.tv/oauth2/authorize'),redirectUri=new URL(this.config.redirectUri);
      auth.searchParams.set('client_id',this.clientId);auth.searchParams.set('redirect_uri',redirectUri.toString());
      auth.searchParams.set('response_type','code');auth.searchParams.set('scope','');auth.searchParams.set('state',state);
      authorizationLocation=auth.toString();stateCookie=this.cookieHeader(STATE_COOKIE,'/',Math.max(1,(expiresAt-now)/1000),state);
    }catch{
      this.sendJson(res,500,{error:'Der Twitch-Anmeldestart konnte nicht vorbereitet werden. Bitte starte den Verknüpfungsvorgang erneut in Discord.'});return;
    }
    try{
      if(!this.store.beginCommunityAccountLinkOAuthState({stateHash,tokenHash,expiresAt,now})){this.sendJson(res,410,{error:'Der Verknüpfungslink wurde bereits verwendet. Starte den Vorgang bitte erneut in Discord.'});return;}
    }catch{
      this.sendJson(res,500,{error:'Der Twitch-Anmeldestart konnte nicht sicher gespeichert werden. Bitte starte den Verknüpfungsvorgang erneut in Discord.'});return;
    }
    res.statusCode=302;res.setHeader('Cache-Control','no-store');res.setHeader('Referrer-Policy','no-referrer');res.setHeader('Set-Cookie',stateCookie);res.setHeader('Location',authorizationLocation);res.end();
  }

